393	// --- Parsers ---
394	
395	// parseIPAddr parses the output of `ip addr show` into a slice of InterfaceInfo.
396	func parseIPAddr(raw string) []InterfaceInfo {
397		var result []InterfaceInfo
398		var current *InterfaceInfo
399	
400		for line := range strings.SplitSeq(raw, "\n") {
401			fields := strings.Fields(line)
402			if len(fields) == 0 {
403				continue
404			}
405	
406			// Interface header: first field is a number with colon (e.g., "1:", "2:")
407			if numStr, ok := strings.CutSuffix(fields[0], ":"); ok {
408				if _, err := strconv.Atoi(numStr); err == nil && len(fields) >= 3 {
409					if current != nil {
410						result = append(result, *current)
411					}
412					name := strings.TrimSuffix(fields[1], ":")
413					// Strip @<parent> suffix for VLAN/tunnel interfaces (e.g., "eth0@if5")
414					if idx := strings.Index(name, "@"); idx != -1 {
415						name = name[:idx]
416					}
417					current = &InterfaceInfo{Name: name, State: parseIfaceState(fields[2])}
418					// Extract MTU from the header line if present (e.g., "mtu 1500")
419					for i := 3; i+1 < len(fields); i++ {
420						if fields[i] == "mtu" {
421							if v, err := strconv.Atoi(fields[i+1]); err == nil {
422								current.MTU = v
423							}
424						}
425					}
426					continue
427				}
428			}
429	
430			// IPv4/IPv6 address lines (indented in the output)
431			if current != nil && len(fields) >= 2 && (fields[0] == "inet" || fields[0] == "inet6") {
432				current.Addresses = append(current.Addresses, fields[1])
433			}
434		}
435	
436		if current != nil {
437			result = append(result, *current)
438		}
439		return result
440	}
441	
442	// parseIfaceState extracts the interface state from its flags string (e.g., "<LOOPBACK,UP,LOWER_UP>").
443	func parseIfaceState(flags string) string {
444		up := strings.ToUpper(flags)
445		switch {
446		case strings.Contains(up, "LOOPBACK"):
447			return "LOOP"
448		case strings.Contains(up, ",UP,") || strings.Contains(up, ",UP>") || up == "<UP>":
449			return "UP"
450		default:
451			return "DOWN"
452		}
453	}
454	
455	// parseIPLink merges MTU and RX/TX error stats from `ip -s link show` into an existing
456	// slice of InterfaceInfo keyed by name. Unmatched interfaces are ignored.
457	func parseIPLink(raw string, ifaces []InterfaceInfo) []InterfaceInfo {
458		// Build a name → index map for fast lookup
459		idx := make(map[string]int, len(ifaces))
460		for i, iface := range ifaces {
461			idx[iface.Name] = i
462		}
463	
464		var currentName string
465		rxHeaderSeen := false
466	
467		for line := range strings.SplitSeq(raw, "\n") {
468			fields := strings.Fields(line)
469			if len(fields) == 0 {
470				continue
471			}
472	
473			// Interface header: "2: eth0: <FLAGS> mtu 1500 ..."
474			if numStr, ok := strings.CutSuffix(fields[0], ":"); ok {
475				if _, err := strconv.Atoi(numStr); err == nil && len(fields) >= 2 {
476					rxHeaderSeen = false
477					name := strings.TrimSuffix(fields[1], ":")
478					if i := strings.Index(name, "@"); i != -1 {
479						name = name[:i]
480					}
481					currentName = name
482					// MTU is already parsed from ip addr show; skip here to avoid duplicates.
483					continue
484				}
485			}
486	
487			if currentName == "" {
488				continue
489			}
490	
491			// "RX:  bytes   packets   errors   dropped ..." header line
492			if fields[0] == "RX:" {
493				rxHeaderSeen = true
494				continue
495			}
496			// "TX:  bytes   packets   errors   dropped ..." header line
497			if fields[0] == "TX:" {
498				rxHeaderSeen = false
499				// Next line holds TX stats
500				continue
501			}
502	
503			// Stat value lines follow the RX: / TX: headers
504			// Format: "  bytes   packets   errors   dropped   missed   mcast"
505			// errors is the 3rd column (index 2)
506			if i, ok := idx[currentName]; ok && len(fields) >= 3 {
507				errVal, err := strconv.ParseInt(fields[2], 10, 64)
508				if err != nil {
509					continue
