	parts := strings.SplitN(strings.TrimPrefix(u.Path, "/"), "/", 3)
	// Expected: ["repository", "<repoName>", ...]
	if len(parts) < 2 || parts[0] != "repository" || parts[1] == "" {
		return "", "", fmt.Errorf("not a Nexus repository path: %q", u.Path)
