			name:    "empty input",
			in:      "",
			wantErr: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			host, repo, err := parseNexusURL(tt.in)
			if tt.wantErr {
				if err == nil {
					t.Fatalf("parseNexusURL(%q) = (%q, %q, nil), want an error", tt.in, host, repo)
