package components

import (
	"strings"

	"github.com/charmbracelet/bubbles/textinput"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"

	"gitlab.com/anthnell/devsecops/devdesk/internal/ui/theme"
)

// WrappedInput is a multi-line text field that word-wraps content at a configurable column.
// It uses textinput.Model internally (correct background) and renders each visual line
// with theme.PadWithBg, ensuring a uniform app background on every line.
//
// Usage:
//
//	field := NewWrappedInput(80, 250, "description (optional)")
//	field.SetDisplayWidth(terminalWidth)
//
//	// In Update():
//	field, cmd = field.Update(msg)
//
//	// In View():
//	return labelStr + "\n" + field.View()
type WrappedInput struct {
	input        textinput.Model
	wrapWidth    int
	displayWidth int
	focused      bool
}

// NewWrappedInput creates a WrappedInput.
// wrapWidth: number of runes per visual line before wrapping (e.g. 80).
// charLimit: maximum total characters allowed (0 = unlimited).
// placeholder: text shown when empty and unfocused.
func NewWrappedInput(wrapWidth, charLimit int, placeholder string) WrappedInput {
	input := textinput.New()
	input.Placeholder = placeholder
	input.CharLimit = charLimit
	input.Width = 4096 // never scrolls internally; display is word-wrapped manually
	theme.StyleTextInput(&input)
	return WrappedInput{
		input:     input,
		wrapWidth: wrapWidth,
	}
}

// SetDisplayWidth sets the full terminal width used for background padding.
// Call this whenever a tea.WindowSizeMsg is received.
func (w *WrappedInput) SetDisplayWidth(width int) {
	w.displayWidth = width
}

// Focus gives keyboard focus to the input and returns the blink command.
func (w *WrappedInput) Focus() tea.Cmd {
	w.focused = true
	return w.input.Focus()
}

// Blur removes keyboard focus from the input.
func (w *WrappedInput) Blur() {
	w.focused = false
	w.input.Blur()
}

// Value returns the current text value.
func (w WrappedInput) Value() string {
	return w.input.Value()
}

// Update handles Bubble Tea messages and returns the updated model.
func (w WrappedInput) Update(msg tea.Msg) (WrappedInput, tea.Cmd) {
	var cmd tea.Cmd
	w.input, cmd = w.input.Update(msg)
	return w, cmd
}

// View renders the word-wrapped content block padded to displayWidth.
// Each line is prefixed with a 2-char indent. When focused, a block cursor
// is drawn at the current rune position.
func (w WrappedInput) View() string {
	value := w.input.Value()
	lines := wrapInputLines(value, w.wrapWidth)
	cursorPos := w.input.Position()

	if len(lines) == 0 {
		if w.focused {
			cur := lipgloss.NewStyle().Background(theme.ColorText).Foreground(theme.ColorBackground).Render(" ")
			return theme.PadWithBg("  "+cur, w.displayWidth)
		}
		return theme.PadWithBg(theme.DimStyle.Render("  "+w.input.Placeholder), w.displayWidth)
	}

	cursorStyle := lipgloss.NewStyle().Background(theme.ColorText).Foreground(theme.ColorBackground)

	var b strings.Builder
	for i, wl := range lines {
		runes := []rune(wl.text)
		lineEnd := wl.startIndex + len(runes)

		var displayLine string
		if w.focused && cursorPos >= wl.startIndex && cursorPos <= lineEnd {
			col := cursorPos - wl.startIndex
			before := string(runes[:col])
			var cur, after string
			if col < len(runes) {
				cur = cursorStyle.Render(string(runes[col]))
				after = string(runes[col+1:])
			} else {
				cur = cursorStyle.Render(" ")
			}
			displayLine = "  " + before + cur + after
		} else {
			displayLine = "  " + wl.text
		}

		b.WriteString(theme.PadWithBg(displayLine, w.displayWidth))
		if i < len(lines)-1 {
			b.WriteString("\n")
		}
	}
	return b.String()
}

// wrappedLine holds one visual line and its start offset in the original rune slice.
type wrappedLine struct {
	text       string
	startIndex int
}

// wrapInputLines splits text into visual lines of at most wrapWidth runes,
// breaking at word boundaries where possible, falling back to a hard break.
func wrapInputLines(text string, wrapWidth int) []wrappedLine {
	if text == "" {
		return nil
	}
	runes := []rune(text)
	var lines []wrappedLine
	start := 0

	for start < len(runes) {
		end := start + wrapWidth
		if end >= len(runes) {
			lines = append(lines, wrappedLine{string(runes[start:]), start})
			break
		}
		// Walk back to the last space within the allowed width.
		breakAt := end
		for breakAt > start && runes[breakAt] != ' ' {
			breakAt--
		}
		if breakAt == start {
			breakAt = end // no space found: hard break at wrapWidth
		}
		lines = append(lines, wrappedLine{string(runes[start:breakAt]), start})
		start = breakAt
		if start < len(runes) && runes[start] == ' ' {
			start++ // consume the breaking space
		}
	}
	return lines
}

package components

import (
	"strings"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"

	"gitlab.com/anthnell/devsecops/devdesk/internal/ui/theme"
)

// DeleteConfirmModal est une boîte de dialogue de confirmation pour suppression
// avec option de suppression immédiate
type DeleteConfirmModal struct {
	title             string
	message           string
	focused           int  // 0 = checkbox, 1 = Yes, 2 = No
	permanentlyRemove bool // Si true, suppression immédiate sans période de grâce
	width             int
	height            int
}

// NewDeleteConfirmModal crée une nouvelle modal de confirmation de suppression
func NewDeleteConfirmModal(title, message string) *DeleteConfirmModal {
	return &DeleteConfirmModal{
		title:             title,
		message:           message,
		focused:           2, // Default sur "No" pour éviter les suppressions accidentelles
		permanentlyRemove: false,
	}
}

// NewDeleteConfirmModalPermanent crée une modal avec la case "immediate deletion" pré-cochée et non modifiable.
// À utiliser quand le projet est déjà marqué pour suppression — seule la suppression permanente est possible.
func NewDeleteConfirmModalPermanent(title, message string) *DeleteConfirmModal {
	return &DeleteConfirmModal{
		title:             title,
		message:           message,
		focused:           2, // Default sur "No"
		permanentlyRemove: true,
	}
}

// DeleteConfirmModalYesMsg est envoyé quand l'utilisateur confirme la suppression
type DeleteConfirmModalYesMsg struct {
	PermanentlyRemove bool
}

// DeleteConfirmModalNoMsg est envoyé quand l'utilisateur annule
type DeleteConfirmModalNoMsg struct{}

// Update met à jour la modal
func (m *DeleteConfirmModal) Update(msg tea.Msg) (*DeleteConfirmModal, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height

	case tea.KeyMsg:
		switch msg.String() {
		case "up", "k":
			// Navigate up
			if m.focused > 0 {
				m.focused--
			}
			return m, nil

		case "down", "j":
			// Navigate down
			if m.focused < 2 {
				m.focused++
			}
			return m, nil

		case "left", "h":
			// Si sur les boutons, aller vers Yes
			if m.focused == 2 {
				m.focused = 1
			}
			return m, nil

		case "right", "l":
			// Si sur les boutons, aller vers No
			if m.focused == 1 {
				m.focused = 2
			}
			return m, nil

		case "tab":
			// Cycle through: checkbox -> Yes -> No -> checkbox
			m.focused = (m.focused + 1) % 3
			return m, nil

		case "shift+tab":
			// Cycle backwards
			m.focused = (m.focused + 2) % 3
			return m, nil

		case " ":
			// Toggle checkbox si focus dessus, sinon confirmer la sélection
			if m.focused == 0 {
				m.permanentlyRemove = !m.permanentlyRemove
				return m, nil
			}
			return m.handleConfirm()

		case "enter":
			return m.handleConfirm()

		case "y", "Y":
			// Raccourci pour Yes
			return m, func() tea.Msg {
				return DeleteConfirmModalYesMsg{PermanentlyRemove: m.permanentlyRemove}
			}

		case "n", "N", "esc":
			// Raccourci pour No
			return m, func() tea.Msg {
				return DeleteConfirmModalNoMsg{}
			}
		}
	}

	return m, nil
}

// handleConfirm gère la confirmation selon l'élément sélectionné
func (m *DeleteConfirmModal) handleConfirm() (*DeleteConfirmModal, tea.Cmd) {
	switch m.focused {
	case 0:
		// Toggle checkbox
		m.permanentlyRemove = !m.permanentlyRemove
		return m, nil
	case 1:
		// Yes
		return m, func() tea.Msg {
			return DeleteConfirmModalYesMsg{PermanentlyRemove: m.permanentlyRemove}
		}
	case 2:
		// No
		return m, func() tea.Msg {
			return DeleteConfirmModalNoMsg{}
		}
	}
	return m, nil
}

// View affiche la modal
func (m *DeleteConfirmModal) View() string {
	var b strings.Builder

	// Titre
	b.WriteString(theme.TitleStyle.Render(m.title))
	b.WriteString("\n\n")

	// Message
	b.WriteString(m.message)
	b.WriteString("\n\n")

	// Checkbox pour suppression immédiate
	checkboxStyle := lipgloss.NewStyle().Background(theme.ColorBackground)
	if m.focused == 0 {
		checkboxStyle = checkboxStyle.Bold(true).Foreground(theme.ColorHighlight)
	}

	checkbox := theme.IconCheckbox
	if m.permanentlyRemove {
		checkbox = theme.IconChecked
	}

	indicator := "  "
	if m.focused == 0 {
		indicator = theme.IconCircleSmall + " "
	}

	checkboxLabel := " Immediate deletion (no grace period)"
	checkboxLine := checkboxStyle.Render(indicator + checkbox + checkboxLabel)
	b.WriteString(checkboxLine)

	// Warning si suppression immédiate activée
	if m.permanentlyRemove {
		b.WriteString("\n")
		warningStyle := lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorHighlight).Italic(true)
		b.WriteString(warningStyle.Render("  " + theme.IconWarning + " This action is irreversible!"))
	}
	b.WriteString("\n\n")

	// Boutons
	yes := theme.RenderButton("Yes", m.focused == 1, "danger")
	no := theme.RenderButton("No", m.focused == 2, "primary")

	buttons := yes + theme.Bg("  ") + no
	b.WriteString(buttons)
	b.WriteString("\n\n")

	return lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorText).
		Border(lipgloss.NormalBorder()).
		BorderForeground(theme.ColorError).
		BorderBackground(theme.ColorBackground).
		Padding(1, 2).
		Render(b.String())
}

